/**
 * The day's painting, and how to prove where it came from.
 *
 * GENERATED by `.ai/tools/fetch_scrolls.py` on 2026-10-01 - do not hand-edit.
 * The generator measured the widths and heights after downscaling, and a
 * hand-typed intrinsic size is a size that is eventually wrong invisibly: the
 * layout reserves the wrong box, the image lands in it, and nothing says so.
 *
 * Thirty-one paintings, one per day of the month, chosen from the Cleveland
 * Museum of Art's CC0 holdings. All thirty-one are public domain in the
 * museum's own sense - `images.web.copyright` is empty and the API's `cc0=1`
 * filter returned them - and the underlying paintings are four to seven
 * centuries old, so the copyright in the photographs expired long before the
 * camera did.
 *
 * See `PROVENANCE.md` beside this file for the per-painting receipt. This file
 * carries only what the interface actually renders.
 *
 * The credited name is the museum's, romanised. It is stored rather than
 * looked up at runtime because a launch screen must not depend on the network,
 * and because a credit that can fail to render is not a credit.
 */

export interface Scroll {
  /** 1-31. `null` when the date has no day in it. */
  readonly day: number
  /** Intrinsic width, measured. */
  readonly width: number
  /** Intrinsic height, measured. */
  readonly height: number
  readonly artist: string
  readonly title: string
  readonly date: string
  /** Where it is held. Rendered in the credit line. */
  readonly museum: string
  readonly accession: string
  /** The museum's page for this object. */
  readonly source: string
}

