/**
 * The image files, resolved by Vite.
 *
 * `?url` rather than a plain import so each entry is a URL string and not a
 * module object, and `eager` because the launch screen needs the URL
 * synchronously on the first paint - a lazy glob would resolve after the
 * screen has already decided it has no painting, which is a blank launch for
 * one frame on every cold start.
 *
 * The images themselves are *not* bundled into the JavaScript: they are emitted
 * as separate files and fetched only when an `<img>` asks for one, so a reader
 * who dismisses the launch screen never downloads any of them.
 */
const FILES = import.meta.glob('./*.jpg', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>

function urlFor(day: number): string {
  const key = `./day-${String(day).padStart(2, '0')}.jpg`
  const found = FILES[key]
  if (found === undefined) {
    throw new Error(`no artwork for day ${day}; the manifest and the folder disagree`)
  }
  return found
}

/**
 * Which painting a date gets.
 *
 * **The day of the month, not a hash of the date.** A month has thirty or
 * thirty-one days, the artwork has thirty-one sheets, and the day of the month
 * is the one function from a date to a painting that a reader can predict and
 * therefore check. A hash would be stable but arbitrary: it would also give the
 * same picture to the 3rd of April and the 3rd of May and no way to say why.
 *
 * February has no 30th or 31st, so `day` is clamped into the range that
 * exists rather than returning nothing - the alternative is a launch screen with
 * a hole in it for five weeks a year.
 */
export function scrollFor(date: Date): Scroll {
  const raw = date.getDate()
  const day = Math.min(SCROLLS.length, Math.max(1, raw))
  const found = SCROLLS[day - 1]
  if (found === undefined) {
    throw new Error(`SCROLLS has no entry for day ${day}`)
  }
  return found
}

/** The URL for the painting this date gets. */
export function scrollUrlFor(date: Date): string {
  return urlFor(scrollFor(date).day)
}

